-- v0.13.3 — Frontend Freeze, Market Commons Guides, Lab Expansion, and Book Covers
-- Baseline: deployed v0.13.2 database. v0.13.2.1–v0.13.2.4 were frontend-only hotfixes.
begin;

-- Release marker
update public.site_settings
set value='"0.13.3"'::jsonb, updated_at=now()
where setting_key='site.version';

insert into public.site_settings(setting_key,category,value,public_read,description)
values ('site.frontend_frozen','site','true'::jsonb,true,'Foundational frontend frozen after v0.13.3 acceptance; future changes are feature- or defect-driven.')
on conflict(setting_key) do update set value=excluded.value,public_read=excluded.public_read,description=excluded.description,updated_at=now();

-- Correct legacy navigation destination.
update public.site_navigation_items
set href='market-commons.html',updated_at=now()
where item_code='TOP_COMMONS';

-- Expand the live frontend Acceptance Console for the freeze gate.
insert into public.qa_acceptance_items(item_code,label,category) values
('HOME','Home / Landing Page','Member Experience'),
('SETTINGS','Member Settings','Member Experience'),
('SUPPORT','Member Support / Admin Queue','Support'),
('TEST_ACCOUNTS','Test Accounts / QA Center','Operations'),
('ERROR_STATES','Loading / Empty / Error States','Quality')
on conflict(item_code) do nothing;

-- Supplemental lab progress for the new database-driven labs.
create table if not exists public.site_lab_progress (
  user_id uuid not null references auth.users(id) on delete cascade,
  lab_id text not null references public.platform_labs(lab_id) on delete cascade,
  status text not null default 'not_started' check (status in ('not_started','in_progress','completed')),
  responses jsonb not null default '{}'::jsonb,
  started_at timestamptz,
  completed_at timestamptz,
  updated_at timestamptz not null default now(),
  primary key(user_id,lab_id)
);
create index if not exists site_lab_progress_user_status_idx on public.site_lab_progress(user_id,status,updated_at desc);
alter table public.site_lab_progress enable row level security;
drop policy if exists "members read own site lab progress" on public.site_lab_progress;
create policy "members read own site lab progress" on public.site_lab_progress
  for select to authenticated using(user_id=auth.uid());
drop policy if exists "members create own site lab progress" on public.site_lab_progress;
create policy "members create own site lab progress" on public.site_lab_progress
  for insert to authenticated with check(user_id=auth.uid());
drop policy if exists "members update own site lab progress" on public.site_lab_progress;
create policy "members update own site lab progress" on public.site_lab_progress
  for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
drop policy if exists "members delete own site lab progress" on public.site_lab_progress;
create policy "members delete own site lab progress" on public.site_lab_progress
  for delete to authenticated using(user_id=auth.uid());
revoke all on public.site_lab_progress from anon,authenticated;
grant select,insert,update,delete on public.site_lab_progress to authenticated;
grant all on public.site_lab_progress to service_role;

