  title=excluded.title,
  book_code=excluded.book_code,
  chapter_number=excluded.chapter_number,
  ticker=excluded.ticker,
  historical_date=excluded.historical_date,
  timeframe=excluded.timeframe,
  lab_type=excluded.lab_type,
  public_sample=excluded.public_sample,
  custom_href=excluded.custom_href,
  sort_order=excluded.sort_order,
  metadata=coalesce(public.platform_labs.metadata,'{}'::jsonb) || excluded.metadata,
  updated_at=now();

