('SITE-001','Platform Navigation & Dashboard — What It Is','SITE_EXCLUSIVE',null,null,null,null,'supplemental',true,true,false,'site-lab.html?lab=SITE-001',60001,'{"track":"site","source_kind":"platform_plus_research","source_ref":"Platform Navigation & Dashboard","chapter_title":null,"skill_group":"Platform Navigation & Dashboard","mode":"what","difficulty":"beginner","what":"Use the member Dashboard as the operating hub for learning, access, settings, support, billing, and activity.","why":"Platform Navigation & Dashboard matters because it helps members turn information into a controlled learning or trading decision instead of relying on memory, excitement, or hindsight.","when":"Use it when you need to resume work, verify access, or change account-level settings.","objective":"Explain what Platform Navigation & Dashboard does, what information it uses, and what it does not replace.","how":["Open Platform Navigation & Dashboard and identify its primary inputs, outputs, and decisions it supports.","Write a one-sentence definition that does not promise prediction or certainty.","List the minimum prerequisite information a member needs before using it.","Identify one adjacent tool that provides different evidence rather than duplicating this tool."],"questions":["What is Platform Navigation & Dashboard?","What problem does it solve?","What information does it not provide?","Which platform area should you use before or after it?"],"data_requirement":"Use the platform fields and source data actually available to the tool; preserve timestamps, provider/feed scope, and unknowns when market data is involved.","historical_anchor":null,"source_urls":[],"tool_href":"dashboard.html","research_provenance":"Site-exclusive exercise designed from the platform workflow, uploaded curriculum, official market-structure/regulatory sources, and stock-market research tools used during the v0.13.3 build.","tags":["site-exclusive","what","platform-navigation-dashboard"]}'::jsonb)
on conflict(lab_id) do update set
  title=excluded.title,
  book_code=excluded.book_code,
  chapter_number=excluded.chapter_number,
  ticker=excluded.ticker,
  historical_date=excluded.historical_date,
  timeframe=excluded.timeframe,
  lab_type=excluded.lab_type,
  public_sample=excluded.public_sample,
  custom_href=excluded.custom_href,
  sort_order=excluded.sort_order,
  metadata=coalesce(public.platform_labs.metadata,'{}'::jsonb) || excluded.metadata,
  updated_at=now();

insert into public.platform_labs(lab_id,title,book_code,chapter_number,ticker,historical_date,timeframe,lab_type,active,registry_visible,public_sample,custom_href,sort_order,metadata) values
('SITE-002','Platform Navigation & Dashboard — Why It Matters & When to Use It','SITE_EXCLUSIVE',null,null,null,null,'supplemental',true,true,false,'site-lab.html?lab=SITE-002',60002,'{"track":"site","source_kind":"platform_plus_research","source_ref":"Platform Navigation & Dashboard","chapter_title":null,"skill_group":"Platform Navigation & Dashboard","mode":"why-when","difficulty":"beginner","what":"Use the member Dashboard as the operating hub for learning, access, settings, support, billing, and activity.","why":"Platform Navigation & Dashboard matters because it helps members turn information into a controlled learning or trading decision instead of relying on memory, excitement, or hindsight.","when":"Use it when you need to resume work, verify access, or change account-level settings.","objective":"Decide when Platform Navigation & Dashboard adds useful evidence and when using it would add noise or false confidence.","how":["Start with a realistic decision that could lead a member to Platform Navigation & Dashboard.","Explain why the tool matters: Use the member Dashboard as the operating hub for learning, access, settings, support, billing, and activity.","State the normal use condition: when you need to resume work, verify access, or change account-level settings.","Write one NO-USE condition where the tool should not control the decision.","Choose the next platform step and explain why."],"questions":["Why does this tool exist?","When should you use Platform Navigation & Dashboard?","When should you *not* rely on it?","What evidence should come from another tool or primary source?"],"data_requirement":"Use the platform fields and source data actually available to the tool; preserve timestamps, provider/feed scope, and unknowns when market data is involved.","historical_anchor":null,"source_urls":[],"tool_href":"dashboard.html","research_provenance":"Site-exclusive exercise designed from the platform workflow, uploaded curriculum, official market-structure/regulatory sources, and stock-market research tools used during the v0.13.3 build.","tags":["site-exclusive","why-when","platform-navigation-dashboard"]}'::jsonb),
('SITE-003','Platform Navigation & Dashboard — Step-by-Step Workflow','SITE_EXCLUSIVE',null,null,null,null,'supplemental',true,true,false,'site-lab.html?lab=SITE-003',60003,'{"track":"site","source_kind":"platform_plus_research","source_ref":"Platform Navigation & Dashboard","chapter_title":null,"skill_group":"Platform Navigation & Dashboard","mode":"how","difficulty":"beginner","what":"Use the member Dashboard as the operating hub for learning, access, settings, support, billing, and activity.","why":"Platform Navigation & Dashboard matters because it helps members turn information into a controlled learning or trading decision instead of relying on memory, excitement, or hindsight.","when":"Use it when you need to resume work, verify access, or change account-level settings.","objective":"Complete a repeatable Platform Navigation & Dashboard workflow and hand the result to the correct next tool.","how":["Open the tool: dashboard.html.","Define the question you are trying to answer before changing filters or entering data.","Enter only the inputs needed for that question and record timestamps/source scope where relevant.","Review the output for missing data, contradictory evidence, and risk implications.","Save or transfer the result into the next appropriate workflow: Lab, Simulator, Watchlist, Journal, or Review."],"questions":["What question did you define before using the tool?","Which inputs materially changed the result?","What did you save or carry forward?","What was the next action and why?"],"data_requirement":"Use the platform fields and source data actually available to the tool; preserve timestamps, provider/feed scope, and unknowns when market data is involved.","historical_anchor":null,"source_urls":[],"tool_href":"dashboard.html","research_provenance":"Site-exclusive exercise designed from the platform workflow, uploaded curriculum, official market-structure/regulatory sources, and stock-market research tools used during the v0.13.3 build.","tags":["site-exclusive","how","platform-navigation-dashboard"]}'::jsonb),
