(product_code,product_type,family,title,short_title,author,publisher,description,active,sort_order,kdp_select,companion_access,book_key_trial_days,direct_digital_enabled,direct_physical_enabled,publication_status,branch_slug,included_lifetime,cover_image_url)
values
('DAY_TRADING_BOOK_1','book','day-trading','The Stock Market: From the Ground Up — Day Trading','Day Trading','J. S. Grant','Crown & Lantern Press','Intraday market structure, discovery, catalysts, setups, risk, execution, management, journaling, replay, and readiness.',true,40,false,true,30,false,false,'coming_soon','day-trading',true,'/assets/images/books/day-trading-book-1.webp'),
('READING_THE_TAPE','book','reading-the-tape','READING THE TAPE — Time & Sales, Level II, and Modern Order Flow','Reading the Tape','J. S. Grant','Crown & Lantern Press','Time & Sales, Level II, quote/depth evidence, liquidity, auctions, execution mechanics, and modern order-flow interpretation.',true,50,false,true,30,false,false,'coming_soon','reading-the-tape',true,'/assets/images/books/reading-the-tape.webp')
